class HitWindow {
  private times: number[] = [];

  record(second: number): void {
    this.times.push(second);
  }

  recentCount(second: number): number {
    // first index whose time is > second - 300
    let lo = 0, hi = this.times.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.times[mid] <= second - 300) lo = mid + 1;
      else hi = mid;
    }
    return this.times.length - lo;
  }
}

